// Generated from src/registry/sources/control-ui/recipes/badge.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const badgeKnobs = ["--cui-badge-radius", "--cui-badge-background", "--cui-badge-foreground", "--cui-badge-border-color"] as const;
export type BadgeKnobStyle = Partial<Record<(typeof badgeKnobs)[number], string>>;

// Generated from src/registry/sources/control-ui/recipes/source-badge.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const sourceBadgeKnobs = [
  "--cui-source-badge-background",
  "--cui-source-badge-foreground",
  "--cui-source-badge-hover-background",
  "--cui-source-badge-hover-foreground",
  "--cui-source-badge-favicon-background",
  "--cui-source-badge-favicon-radius",
] as const;
export type SourceBadgeKnobStyle = Partial<Record<(typeof sourceBadgeKnobs)[number], string>>;

@layer components {
  :where([data-control-family="badge"][data-source-badge][data-slot="root"]) {
    block-size: calc(var(--spacing) * 6);
    gap: calc(var(--spacing) * 1.5);
    padding-block: 0;
    padding-inline: calc(var(--spacing) * 1.5) calc(var(--spacing) * 2);
    --cui-source-badge-background: var(--background);
    --cui-source-badge-foreground: var(--muted-foreground);
    --cui-source-badge-hover-background: oklch(from var(--muted) l c h / 0.6);
    --cui-source-badge-hover-foreground: var(--foreground);
    --cui-source-badge-favicon-background: var(--muted);
    --cui-source-badge-favicon-radius: var(--radius-sm);
    background: var(--cui-source-badge-background);
    color: var(--cui-source-badge-foreground);
    transition-property: color, background-color, border-color, outline-color, text-decoration-color, fill, stroke;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
    font-weight: var(--font-weight-normal);
  }

  @media (hover: hover) {
    :where([data-control-family="badge"][data-source-badge][data-slot="root"]:hover) {
      background: var(--cui-source-badge-hover-background);
      color: var(--cui-source-badge-hover-foreground);
    }
  }

  :where([data-control-family="badge"][data-source-badge][data-slot="root"] [data-slot="label"]) {
    max-inline-size: calc(var(--spacing) * 44);
  }

  :where([data-control-family="avatar"][data-source-badge-favicon][data-slot="root"]) {
    inline-size: calc(var(--spacing) * 3.5);
    block-size: calc(var(--spacing) * 3.5);
    --cui-avatar-radius: var(--cui-source-badge-favicon-radius);
    --cui-avatar-fallback-background: var(--cui-source-badge-favicon-background);
    --cui-avatar-fallback-foreground: var(--cui-source-badge-foreground);
    background: var(--cui-source-badge-favicon-background);
    border-radius: var(--cui-source-badge-favicon-radius);
  }
}

@property --cui-source-badge-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-source-badge-foreground {
